'use strict';
function validate(map){const ids=new Set(),members=new Set();for(const t of map.triggers){if(typeof t.id!=='string'||!t.id.length||t.id.length>80||Object.getOwnPropertyNames(Object.prototype).includes(t.id)||ids.has(t.id)||!Number.isFinite(t.x)||t.x<0||t.x>map.width||t.yMin!==10||t.yMax!==530||!Number.isInteger(t.warningTicks)||t.warningTicks<78||t.warningTicks>600||!Array.isArray(t.members)||!t.members.length||t.cue!=='visible-motion-warning')throw Error('Invalid arrival trigger');ids.add(t.id);for(const id of t.members){const o=map.obstacles.find(o=>o.id===id);if(!o||members.has(id)||o.trigger_id!==t.id||!['vertical_armor_slider','horizontal_armor_slider'].includes(o.mechanic_kind))throw Error('Invalid shared trigger member');members.add(id);}}for(const o of map.obstacles)if(o.trigger_id&&!ids.has(o.trigger_id))throw Error('Missing trigger reference');}
function cross(map,s,before,teleported){if(teleported)return;for(const t of map.triggers){if(s.triggerState[t.id]!==undefined)continue;if(before.x<t.x&&s.x>=t.x){const u=(t.x-before.x)/(s.x-before.x),y=before.y+u*(s.y-before.y);if(y>=t.yMin&&y<=t.yMax){const activationTick=s.tick+1;s.triggerState[t.id]={activationTick,crossingTick:s.tick,crossingX:t.x,crossingY:y};s.events.push({tick:s.tick,type:'trigger_enter',id:t.id,activationTick,warningTicks:t.warningTicks,members:t.members});}}}}
function descriptor(map,o,tick,state,index){if(!o.trigger_id)return o;const t=index?.get(o.trigger_id)||map.triggers.find(t=>t.id===o.trigger_id),activation=state?.triggerState?.[t.id]?.activationTick,local=activation===undefined?-1:tick-activation-t.warningTicks;return{...o,motion:{...o.motion,amplitude_px:local<0?0:o.motion.amplitude_px*Math.min(1,local/12),phase_rad:o.motion.phase_rad-(activation===undefined?0:activation+t.warningTicks)/120*2*Math.PI/o.motion.period_s}};}
function cue(map,o,tick,state,index){if(!o.trigger_id)return null;const t=index?.get(o.trigger_id)||map.triggers.find(t=>t.id===o.trigger_id),activation=state?.triggerState?.[t.id]?.activationTick;return{type:'motion-warning',axis:o.mechanic_kind==='vertical_armor_slider'?'vertical':'horizontal',triggered:activation!==undefined,warningTicksRemaining:activation===undefined?null:Math.max(0,activation+t.warningTicks-tick),active:activation!==undefined&&tick>=activation+t.warningTicks};}
function validateState(map,s){if(!s.triggerState||typeof s.triggerState!=='object'||Array.isArray(s.triggerState))throw Error('Invalid trigger state');for(const[id,a]of Object.entries(s.triggerState)){const t=map.triggers.find(t=>t.id===id);if(!t||!Number.isInteger(a.activationTick)||!Number.isInteger(a.crossingTick)||a.activationTick!==a.crossingTick+1||a.activationTick>s.tick+1||a.crossingTick<0||a.crossingX!==t.x||!Number.isFinite(a.crossingY)||a.crossingY<10||a.crossingY>530)throw Error('Invalid trigger activation checkpoint');}}
module.exports={validate,cross,descriptor,cue,validateState};
